insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_hourly_earnings,annualised_median_salary,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('NL:early-childhood-teacher','2026-08-12',null,15.63,30876,20,0,0,0,12,4,0,3,3,42,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2342 Early Childhood Educators, constrained to childcare/pedagogical early-childhood education rather than licensed primary teaching.','shortage_note','UWV reports nearly 7,600 childcare vacancies at end-2025 and especially high demand for pedagogical employees; strong 20/20.','visa_basis','No occupation-specific Dutch immigration fast track; employment remains route-, employer-, sponsor- and permit-dependent; 3/10.','salary_method','Studiekeuze123 Pedagogisch Educatief Professional associate-degree estimated graduate starting salary EUR 2,573/month, annualised to EUR 30,876; transparent early-career proxy, not an occupation median; 4/10.','entry_basis','A two-year associate-degree pedagogical route can provide structured entry alongside other qualifying childcare diplomas; 12/15.','entry_burden_basis','No universal teacher register, but childcare qualification, Dutch-language and role-specific training requirements materially constrain entry; 3/5.'),'2026-08-12'),
('NL:primary-school-teacher','2026-08-12',null,20.53,40572,20,0,0,0,8,6,0,3,2,39,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2341 Primary School Teachers.','shortage_note','UWV Q1 2026 classifies primary-school teachers as very tight and expects persistent shortages, with particularly severe pressure in the Randstad; 20/20.','visa_basis','Teacher shortage does not create an occupation-list immigration fast track; standard Dutch work/residence rules apply; 3/10.','salary_method','Studiekeuze123 Opleiding tot Leraar Basisonderwijs estimated graduate starting salary EUR 3,381/month, annualised to EUR 40,572; 6/10.','entry_basis','The standard pabo is a four-year hbo bachelor, with defined academic and side-entry alternatives; 8/15.','entry_burden_basis','A recognised teaching qualification is required and foreign qualifications require DUO recognition for permanent teaching; 2/5.'),'2026-08-12'),
('NL:secondary-school-teacher','2026-08-12',null,20.01,39540,15,0,0,0,8,6,0,3,2,34,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2330 Secondary Education Teachers; subject-specific teaching-authorisation scope.','shortage_note','UWV expects a secondary-teacher shortage above 2,500 FTE in 2026, with the strongest shortages concentrated in exact sciences, informatics, Dutch and several languages; strong but non-uniform 15/20.','visa_basis','No occupation-specific Dutch immigration fast track; 3/10.','salary_method','Studiekeuze123 second-degree Pedagogiek teacher bachelor estimated graduate starting salary EUR 3,295/month, annualised to EUR 39,540; used as a transparent teacher-programme proxy rather than a national secondary-teacher median; 6/10.','entry_basis','Subject-specific first- or second-degree teacher programmes are normally degree-level routes; 8/15.','entry_burden_basis','Applicable subject/school-level teaching authorisation is required, and foreign qualifications require DUO recognition; 2/5.'),'2026-08-12'),
('NL:special-education-teacher','2026-08-12',null,20.53,40572,15,0,0,0,8,6,0,3,2,34,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2352 Special Needs Teachers, constrained to Dutch special primary / special secondary education settings.','shortage_note','Special education sits within the persistent primary/secondary teacher shortage, but no separate current national vacancy intensity is used; 15/20.','visa_basis','No special-education occupation-specific immigration fast track; 3/10.','salary_method','Studiekeuze123 pabo estimated graduate starting salary EUR 3,381/month, annualised to EUR 40,572; used only as an early-career teaching proxy; 6/10.','entry_basis','Primary or secondary teaching authorisation is required according to the setting, with additional SEN study frequently preferred; 8/15.','entry_burden_basis','Teaching authorisation is mandatory and foreign qualifications require DUO recognition; 2/5.'),'2026-08-12'),
('NL:social-worker','2026-08-12',null,17.51,34596,10,0,0,0,8,4,0,3,5,30,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2635 Social Work and Counselling Professionals, social-worker scope.','shortage_note','UWV reports strong recent employment and vacancy growth in social work and sector forecasts still show staffing shortages, while newer long-run evidence suggests maatschappelijk werkers may become somewhat less tight; moderate 10/20.','visa_basis','No social-worker-specific Dutch immigration fast track; standard work/residence routes remain employer- and permit-dependent; 3/10.','salary_method','Studiekeuze123 Social Work hbo bachelor estimated graduate starting salary EUR 2,883/month, annualised to EUR 34,596; 4/10.','entry_basis','The four-year hbo Social Work bachelor is the main direct professional route; 8/15.','entry_burden_basis','Generic social work is not universally registered; task-specific SKJ/BIG requirements can apply in narrower settings but are not imposed on the whole profile; 5/5.'),'2026-08-12'),
('NL:youth-worker','2026-08-12',null,17.51,34596,10,0,0,0,8,4,0,3,4,29,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 3412 Social Work Associate Professionals, youth-services and practical youth-support scope.','shortage_note','UWV reports substantial jeugdzorg employment growth and continuing vacancies, but 2025 demand eased from its prior peak and matching problems are partly qualitative; moderate 10/20.','visa_basis','No youth-worker-specific Dutch immigration fast track; 3/10.','salary_method','Studiekeuze123 Social Work estimated graduate starting salary EUR 2,883/month, annualised to EUR 34,596; pathway proxy; 4/10.','entry_basis','Social Work/Pedagogiek degree routes provide structured professional entry; 8/15.','entry_burden_basis','SKJ is task-dependent rather than universal: complex/high-risk jeugdhulp can require a registered professional, so accessibility is reduced slightly; 4/5.'),'2026-08-12'),
('NL:community-worker','2026-08-12',null,17.51,34596,10,0,0,0,8,4,0,3,5,30,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 3412 Social Work Associate Professionals, community-services and neighbourhood-support scope.','shortage_note','UWV reports rising employment and vacancies across social work, but no separate national community-worker shortage series is used; moderate 10/20.','visa_basis','No community-worker-specific Dutch immigration fast track; 3/10.','salary_method','Studiekeuze123 Social Work estimated graduate starting salary EUR 2,883/month, annualised to EUR 34,596; pathway proxy; 4/10.','entry_basis','Social Work and related hbo routes provide structured entry into community and participation work; 8/15.','entry_burden_basis','No universal statutory community-worker register; 5/5.'),'2026-08-12'),
('NL:counsellor','2026-08-12',null,16.45,32496,0,0,0,0,8,4,0,3,5,20,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2635 Social Work and Counselling Professionals, constrained to broad non-clinical counselling and guidance rather than protected BIG psychologist/psychotherapist practice.','shortage_note','The reviewed current UWV evidence does not establish a broad counsellor shortage, and longer-run evidence points to some easing in psychology/social-work labour markets; 0/20.','visa_basis','No counsellor-specific Dutch immigration fast track; 3/10.','salary_method','Studiekeuze123 Toegepaste Psychologie hbo bachelor estimated graduate starting salary EUR 2,708/month, annualised to EUR 32,496; 4/10.','entry_basis','Applied Psychology, Social Work and related degree routes provide structured entry; 8/15.','entry_burden_basis','Generic counsellor is not universally statutorily registered; narrower clinical practice can trigger separate BIG/professional requirements; 5/5.'),'2026-08-12')
